t.script:
function toggleFAQ(btn) {
  var answer  = btn.nextElementSibling;
  var chevron = btn.querySelector('.faq-chevron');
  var open    = !answer.classList.contains('hidden');
  answer.classList.toggle('hidden', open);
  chevron.style.transform = open ? '' : 'rotate(180deg)';
}
function filterFAQ(q) {
  var term = q.toLowerCase().trim();
  document.querySelectorAll('.faq-item').forEach(function (el) {
    if (!term) { el.style.display = ''; return; }
    var match = el.dataset.question.includes(term) || el.dataset.answer.includes(term);
    el.style.display = match ? '' : 'none';
  });
}
